local config = {
  ui_story_5048_50480101_1_dialog_content = "<color=#e8d9bb>Chirp, chirp, screech...</color>",
  ui_story_5048_50480101_2_dialog_content = "<color=#e8d9bb>Twin Pavilions Bay - Western District</color>",
  ui_story_5048_50480101_3_dialog_content = "Your Highness?",
  ui_story_5048_50480101_4_dialog_content = "<size=50>Princess Dantang!</size>",
  ui_story_5048_50480101_5_dialog_content = "Hmm?",
  ui_story_5048_50480101_6_dialog_content = "Your eyes were closed so tightly, Your Highness, and you were so silent... Pray tell, are you feeling any kind of discomfort?",
  ui_story_5048_50480101_7_dialog_content = "Sorry for worrying you, Jiu, I was just focusing on this wonderfully sweet piano piece.",
  ui_story_5048_50480101_8_dialog_content = "Listen—it's as gentle as water, but it also possesses such a grandiose elegance. It's completely different from the instruments of Longzhou. What a treat for the ears.",
  ui_story_5048_50480101_9_dialog_content = "If I get the chance in the future, I'd love to play alongside a pianist, and then perhaps you can perform a sword dance by my side...",
  ui_story_5048_50480101_10_dialog_content = "You're a true visionary, Your Highness.",
  ui_story_5048_50480101_11_dialog_content = "Don't you think it's strange? They say <color=#FFB400>Twin Pavilions Bay</color> enjoys an abundance of rainfall and a pleasant climate during this season... However, it has been so hot and dry recently.",
  ui_story_5048_50480101_12_dialog_content = "Is this your first time at Twin Pavilions Bay?",
  ui_story_5048_50480101_13_dialog_content = "The weather's been kinda unusual in Twin Pavilions Bay this year. We're all looking forward to a cool sea breeze and a good rain.",
  ui_story_5048_50480101_14_dialog_content = "Oops, sorry, I got a bit off-topic. Here's your order, all the dishes you ordered.",
  ui_story_5048_50480101_15_dialog_content = "We hope the beautiful scenery can dispel any discomfort from the hot weather. Enjoy your meal.",
  ui_story_5048_50480101_16_dialog_content = "As expected from the most famous restaurant in Twin Pavilions Bay—the service here is truly exceptional.",
  ui_story_5048_50480101_17_dialog_content = "Your Highness, there's one thing I still don't quite understand.",
  ui_story_5048_50480101_18_dialog_content = "Little Longzhou in the east of the city is home to many restaurants serving the Longzhou-style dishes to which you're so accustomed.",
  ui_story_5048_50480101_19_dialog_content = "Why then do you insist on frequenting this Astra restaurant in the west of the city when hunger strikes?",
  ui_story_5048_50480101_20_dialog_content = "The first step of diplomacy is understanding local customs and traditions, and the first step in acquiring such an understanding is...",
  ui_story_5048_50480101_21_dialog_content = "Well, naturally, starting off with local food is the quickest way.",
  ui_story_5048_50480101_22_dialog_content = "You're absolutely right, Your Highness.",
  ui_story_5048_50480101_23_dialog_content = "Hmm? Forgive my negligence, I should have asked for chopsticks to be prepared for our table. I'll call the waiter.",
  ui_story_5048_50480101_24_dialog_content = "Look, Jiu, these knives and forks are the cutlery here.",
  ui_story_5048_50480101_25_dialog_content = "Knives and forks... as cutlery? Why do they seem more like personal weapons to me?",
  ui_story_5048_50480101_26_dialog_content = "Haha. I know you have to practice your martial arts all day long, but you really need to read some of the books I gave you when you have time. Learn something about the culture here.",
  ui_story_5048_50480101_27_dialog_content = "Yes...",
  ui_story_5048_50480101_28_dialog_content = "Well, if the cutlery's ready, why aren't you eating, Your Highness?",
  ui_story_5048_50480101_29_dialog_content = "I was just wondering how you were going to eat with that mask on?",
  ui_story_5048_50480101_30_dialog_content = "Your Highness, I'll serve you as you dine, of course.",
  ui_story_5048_50480101_31_dialog_content = "Still not used to showing your face in public?",
  ui_story_5048_50480101_32_dialog_content = "I'm afraid that my appearance may offend Your Highness's eyes, rendering Your Highness unable to eat...",
  ui_story_5048_50480101_33_dialog_content = "Fine, but haven't I told you that not even the word \"beautiful\" itself does your looks justice? Why do you still not believe me?",
  ui_story_5048_50480101_34_dialog_content = "Oh, must I eat all this delicious food alone? Are you that eager to see me suffer from indigestion?",
  ui_story_5048_50480101_35_dialog_content = "I would never dream of such a thing!",
  ui_story_5048_50480101_36_dialog_content = "Ahem... Come on then, have a try.",
  ui_story_5048_50480101_37_dialog_content = "... Yes, Your Highness!",
  ui_story_5048_50480101_38_dialog_content = "<color=#e8d9bb>Jiu carefully tried all the dishes.</color>",
  ui_story_5048_50480101_39_dialog_content = "What do you think?",
  ui_story_5048_50480101_40_dialog_content = "Your Highness, I have tasted everything, and you can rest assured that the food has not been poisoned.",
  ui_story_5048_50480101_41_dialog_content = "I want to know what you think of the taste. Is it to your liking?",
  ui_story_5048_50480101_42_dialog_content = "That... I wasn't paying attention.",
  ui_story_5048_50480101_43_dialog_content = "Next time, savor each mouthful carefully with me. Be sure not to waste these rare delicacies again.",
  ui_story_5048_50480101_44_dialog_content = "I see. Your Highness did not intend for me to test the food for poison...",
  ui_story_5048_50480101_45_dialog_content = "Of course. How else will you be able to enjoy this delicious food with me?",
  ui_story_5048_50480101_46_dialog_content = "Your Highness, I ask that you wait a moment!",
  ui_story_5048_50480101_47_dialog_content = "Upon closer inspection just now, I realized something...",
  ui_story_5048_50480101_48_dialog_content = "This Stone Kiln Pizza's filling hasn't actually been baked into the pastry...",
  ui_story_5048_50480101_49_dialog_content = "This Beef Roayl hasn't been cooked properly! Just look at all the streaks of blood running through it!",
  ui_story_5048_50480101_50_dialog_content = "And this Honey-glazed Seasonal Salad clearly contains raw vegetables! They haven't been cooked at all!",
  ui_story_5048_50480101_51_dialog_content = "Can such carelessly crafted dishes really be called the delicacies of Twin Pavilions Bay?",
  ui_story_5048_50480101_52_dialog_content = "Calm down, Jiu—don't be impatient. As the saying goes, the environment plays a significant part in one's development.",
  ui_story_5048_50480101_53_dialog_content = "Bear in mind, regional differences in diet exist among the various vassal kingdoms of Longzhou, and these differences are even more distinct in Astra, as it is separated from us by a vast ocean.",
  ui_story_5048_50480101_54_dialog_content = "Learning to appreciate the cuisines of different regions is another of the lessons we must learn on our journey across the world.",
  ui_story_5048_50480101_55_dialog_content = "This Stone Kiln Pizza is not one of our Longzhou pies.",
  ui_story_5048_50480101_56_dialog_content = "This pizza has been specially baked in a high-temperature stone kiln, and should ideally boast a crispy crust, full filling, and fresh, fragrant cheese.",
  ui_story_5048_50480101_57_dialog_content = "What about this Beef Royal?",
  ui_story_5048_50480101_58_dialog_content = "In Longzhou, we tend to stir-fry our meat until it's smooth and tender, and we flavor it with different seasonings.",
  ui_story_5048_50480101_59_dialog_content = "However, this Beef Royal strives to preserve the original flavor of the ingredients to the greatest degree possible. The meat is fresh, tender, and juicy, and melts in your mouth...",
  ui_story_5048_50480101_60_dialog_content = "If the quality of the beef had not been strictly controlled from as early as the breeding stage, such a taste would have been impossible to produce.",
  ui_story_5048_50480101_61_dialog_content = "They say that in the past, only the prestigious Lumo Noble was allowed to taste this dish.",
  ui_story_5048_50480101_62_dialog_content = "I see... And what's the story behind this Honey-glazed Seasonal Salad?",
  ui_story_5048_50480101_63_dialog_content = "These vegetables are indeed very fresh and are present in great variety. In fact, many of them are not locally grown.",
  ui_story_5048_50480101_64_dialog_content = "A restaurant that can provide fresh vegetables to diners from other places in such sweltering heat...",
  ui_story_5048_50480101_65_dialog_content = "Whether it's maintaining good faith or storing and preserving food, everything they do is first-class.",
  ui_story_5048_50480101_66_dialog_content = "The only problem is that this dressing is a little too sickly sweet for my taste. If only customers could choose their own sauces.",
  ui_story_5048_50480101_67_dialog_content = "Your Highness, though you have only recently become acquainted with the delicacies of Astra, you have already developed such a profound understanding of them... You're indeed the crown jewel of the Ye Kingdom!",
  ui_story_5048_50480101_68_dialog_content = "Jiu, why have you been flattering me so much these days?",
  ui_story_5048_50480101_69_dialog_content = "Could it be that you learned a few tricks from some <color=#FFB400>smooth talker</color> aboard the ship on our way here?",
  ui_story_5048_50480101_70_dialog_content = "If Your Highness doesn't like it, I will say less.",
  ui_story_5048_50480101_71_dialog_content = "Jiu, you really need to learn how to recognize and react to playful teasing...",
  ui_story_5048_50480101_72_dialog_content = "Hmm?",
  ui_story_5048_50480101_73_dialog_content = "What do you think you're doing?!",
  ui_story_5048_50480101_74_dialog_content = "Ah...",
  ui_story_5048_50480101_75_dialog_content = "You're scaring them.",
  ui_story_5048_50480101_76_dialog_content = "Forgive my rudeness.",
  ui_story_5048_50480101_77_dialog_content = "But you disturbed the two of us in the middle of our meal. What is the matter?",
  ui_story_5048_50480101_78_dialog_content = "Eh, here is the thing.",
  ui_story_5048_50480101_79_dialog_content = "Our boss, Mr. Ernest, just heard your feedback on our dishes, and he was pleasantly surprised.",
  ui_story_5048_50480101_80_dialog_content = "\"Having such spot-on insights into our local cuisine on your first try is truly remarkable.\"",
  ui_story_5048_50480101_81_dialog_content = "Our boss wants to invite both of you to our kitchen and discuss the art of cooking if you have the time for it.",
  ui_story_5048_50480101_82_dialog_content = "Would you both consider gracing us with your presence?",
  ui_story_5048_50480101_83_dialog_content = "You're too kind, I just gave some frank opinions that might not be conventional earlier.",
  ui_story_5048_50480101_84_dialog_content = "It's very generous of the proprietor to invite us, and his broad-mindedness is truly admirable. We'd be more than happy to accept your invitation.",
  ui_story_5048_50480101_85_dialog_content = "Your Highness! We're new here, and are not yet familiar with the local customs.",
  ui_story_5048_50480101_86_dialog_content = "If we rashly accept an invitation from a stranger and vanish from public sight, it might...",
  ui_story_5048_50480101_87_dialog_content = "If you know me at all, you should know that I'm not exactly some weakling lacking the strength to defend herself.",
  ui_story_5048_50480101_88_dialog_content = "Besides, am I not accompanied by a bodyguard wielding unparalleled martial arts skills?",
  ui_story_5048_50480101_89_dialog_content = "Of course, I'll naturally be here to protect you.",
  ui_story_5048_50480101_90_dialog_content = "Although we haven't yet had a chance to discuss the artistry of the piano with the pianist... discussing delicacies with a gourmet first is also a wonderful opportunity.",
  ui_story_5048_50480101_91_dialog_content = "And so, I ask that you lead the way, if it pleases you.",
  ui_story_5048_50480101_92_dialog_content = "Esteemed guests, this way, please.",
  ui_story_5048_50480101_93_dialog_content = "<color=#e8d9bb>A series of clinks and clatters!</color>",
  ui_story_5048_50480101_94_dialog_content = "Oh no, is it possible that someone dropped the plates while serving? The boss is gonna be mad again...",
  ui_story_5048_50480101_95_dialog_content = "I-I need some help over here!",
  ui_story_5048_50480101_96_dialog_content = "Help!",
  ui_story_5048_50480101_97_dialog_content = "Huh? Is that...",
  ui_story_5048_50480101_98_dialog_content = "Li Tianxian?!",
  ui_story_5048_50480201_1_dialog_content = "<color=#e8d9bb>A while back</color>",
  ui_story_5048_50480201_2_dialog_content = "<color=#e8d9bb>Chirp, chirp, screech...</color>",
  ui_story_5048_50480201_3_dialog_content = "Gold melon shriveled.",
  ui_story_5048_50480201_4_dialog_content = "Silver date sank.",
  ui_story_5048_50480201_5_dialog_content = "Empty belly rumbles.",
  ui_story_5048_50480201_6_dialog_content = "Pauper's pocket's clank!",
  ui_story_5048_50480201_7_dialog_content = "... Squawk, Jabber, can the two of you settle down a moment?",
  ui_story_5048_50480201_8_dialog_content = "Holiday! Holiday!",
  ui_story_5048_50480201_9_dialog_content = "Go home! Go home!",
  ui_story_5048_50480201_10_dialog_content = "If business doesn't pick up soon, where will we get the money for the golden melons and silver dates",
  ui_story_5048_50480201_11_dialog_content = "But don't worry. I roam the world, wandering here and there. When have I ever let you two go hungry?",
  ui_story_5048_50480201_12_dialog_content = "Wait just a little longer...",
  ui_story_5048_50480201_13_dialog_content = "Hmm?",
  ui_story_5048_50480201_14_dialog_content = "Just look, is our change in fate not close at hand?",
  ui_story_5048_50480201_15_dialog_content = "Welcome! Sir, are you dining alone?",
  ui_story_5048_50480201_16_dialog_content = "I'm looking for someone.",
  ui_story_5048_50480201_17_dialog_content = "He's inside—I can find him myself, there's no need to put yourself out!",
  ui_story_5048_50480201_18_dialog_content = "Okay, sir.",
  ui_story_5048_50480201_19_dialog_content = "Amazing... It's so spacious and bright in here, and far cooler than outside. What a marvelous little gem I've found myself in.",
  ui_story_5048_50480201_20_dialog_content = "Now, it's time to get searching. Let me see...",
  ui_story_5048_50480201_21_dialog_content = "Well, stone the crows!",
  ui_story_5048_50480201_22_dialog_content = "It's clear to see you're a person of great wealth and stature, but what has forced your eyebrows into a furrow and filled your face with gloom this day?",
  ui_story_5048_50480201_23_dialog_content = "Something's troubling you.",
  ui_story_5048_50480201_24_dialog_content = "Whatever it is, I don't think it has anything to do with you.",
  ui_story_5048_50480201_25_dialog_content = "Oh really? But how could it not have anything to do with me?",
  ui_story_5048_50480201_26_dialog_content = "Allow me to introduce myself. I am Li Tianxian, fresh off the ferry from Longzhou.",
  ui_story_5048_50480201_27_dialog_content = "Though I cannot speak to my own abilities, some regard me as something of a grand artisan.",
  ui_story_5048_50480201_28_dialog_content = "An artisan, eh? You're not a chef, by any chance?",
  ui_story_5048_50480201_29_dialog_content = "No, no, no. You see, life and death are dictated by fate, wealth and prestige by the heavens. I'm a master of the principle of Yin and Yang and the Five Elements theory—one with a guaranteed ninety percent minimum forecast accuracy rate.",
  ui_story_5048_50480201_30_dialog_content = "My craft is known as <color=#FFB400>divination</color>.",
  ui_story_5048_50480201_31_dialog_content = "I can map out the course of your destiny, guide you safely past the pitfalls of fate, and sometimes... even change the future, defying the very heavens.",
  ui_story_5048_50480201_32_dialog_content = "Whatever difficulty you're facing, place it in my hands and I'll provide you with resolution.",
  ui_story_5048_50480201_33_dialog_content = "Satisfaction guaranteed!",
  ui_story_5048_50480201_34_dialog_content = "Total accuracy, or your money back!",
  ui_story_5048_50480201_35_dialog_content = "Sir, if you're not here for dining, please refrain from disturbing our esteemed guests and leave now.",
  ui_story_5048_50480201_36_dialog_content = "Now, now, now... There's a time and a place for everything, and at this time, I have yet to finish speaking with your distinguished guest.",
  ui_story_5048_50480201_37_dialog_content = "Won't you at least think about it?",
  ui_story_5048_50480201_38_dialog_content = "If you're not satisfied, I'll be on my way.",
  ui_story_5048_50480201_39_dialog_content = "Let him take a seat.",
  ui_story_5048_50480201_40_dialog_content = "Mr. Victor...?",
  ui_story_5048_50480201_41_dialog_content = "Don't worry about it, you go ahead and get back to your duties.",
  ui_story_5048_50480201_42_dialog_content = "Heheh, my friend, you should try to be more respectful to your customers in the future.",
  ui_story_5048_50480201_43_dialog_content = "...",
  ui_story_5048_50480201_44_dialog_content = "Mr. Victor, everyone who works here seems to know you. You must be a regular customer.",
  ui_story_5048_50480201_45_dialog_content = "Yes, you could say that.",
  ui_story_5048_50480201_46_dialog_content = "Thank you for your kind help just now!",
  ui_story_5048_50480201_47_dialog_content = "Encountering a soul as kind and righteous as yours is a rare occurrence these days. As such, I'll grant you a divination at a discount price.",
  ui_story_5048_50480201_48_dialog_content = "If your powers really are as impressive as you claim, I won't treat you unfairly.",
  ui_story_5048_50480201_49_dialog_content = "Now, let me see what you can do.",
  ui_story_5048_50480201_50_dialog_content = "<color=#e8d9bb>Whooooosh!!</color>",
  ui_story_5048_50480201_51_dialog_content = "Yin Rat above, Yang Ox below.",
  ui_story_5048_50480201_52_dialog_content = "Good sir, the divination shows a rat riding an ox's back.",
  ui_story_5048_50480201_53_dialog_content = "The alternation of yin and yang, universal conflict—all discord is interlinked with cause and effect.",
  ui_story_5048_50480201_54_dialog_content = "The image shown in this hexagram reveals your future strategy for overcoming this conflict.",
  ui_story_5048_50480201_55_dialog_content = "Hmm? Let's hear it then.",
  ui_story_5048_50480201_56_dialog_content = "Firstly, if you don't want to become a stepping stone for the success of others, you must take extra precautions against those who would do you harm.",
  ui_story_5048_50480201_57_dialog_content = "How can I know who's trying to do me in?",
  ui_story_5048_50480201_58_dialog_content = "Worry not, sir, for this divination has a second meaning.",
  ui_story_5048_50480201_59_dialog_content = "Although you may encounter those of despicable natures, you'll always receive the aid of the virtuous in times of peril, finding a new path forward and turning misfortunes into blessings.",
  ui_story_5048_50480201_60_dialog_content = "The virtuous, you say?",
  ui_story_5048_50480201_61_dialog_content = "That is to say, at the eleventh hour, someone will come to your rescue, and all of your problems will be resolved with ease.",
  ui_story_5048_50480201_62_dialog_content = "And you'll always be blessed with good luck, throughout your entire life.",
  ui_story_5048_50480201_63_dialog_content = "Hahaha! Excellent! I'll gladly pay for such auspicious words. I hope I really will be blessed with good luck, just like you said.",
  ui_story_5048_50480201_64_dialog_content = "Oh, you truly are a kind soul... My noble benefactor, please accept my deepest gratitude, and an even deeper bow from your humble servant.",
  ui_story_5048_50480201_65_dialog_content = "Hmph! You consider yourself an artisan, just because you know how to tell people what they want to hear?",
  ui_story_5048_50480201_66_dialog_content = "And the fact that you're doing all this for a little coin makes you even more contemptible.",
  ui_story_5048_50480201_67_dialog_content = "...",
  ui_story_5048_50480201_68_dialog_content = "Sir, I bear you no ill will. For what reason do you feel the need to rebuke me so harshly?",
  ui_story_5048_50480201_69_dialog_content = "Such words do not affect me personally, but if they put a damper on your own mood, surely your losses outweigh your gains.",
  ui_story_5048_50480201_70_dialog_content = "Is the food today to your liking?",
  ui_story_5048_50480201_71_dialog_content = "(His words are harsh, but he doesn't seem to have it in for me...)",
  ui_story_5048_50480201_72_dialog_content = "Yes, it's delicious.",
  ui_story_5048_50480201_73_dialog_content = "How would you know what it tastes like when you haven't even taken a bite?",
  ui_story_5048_50480201_74_dialog_content = "Is this what you really want from life? To pretend everything is fine and pursue some superficial semblance of peace?",
  ui_story_5048_50480201_75_dialog_content = "You're a gourmet. Writing off any dish placed before you as delicious is the beginning of the end for a man of standards!",
  ui_story_5048_50480201_76_dialog_content = "There's more than one set of standards in this world, and I have my own way of seeing things.",
  ui_story_5048_50480201_77_dialog_content = "Simply pointing out the unpleasant truths of the world isn't enough to survive in it. If we can't even achieve a superficial peace, what hope do we have of ever achieving real peace?!",
  ui_story_5048_50480201_78_dialog_content = "(Tch... I'm afraid another mystery may lie behind the confrontation between these two.)",
  ui_story_5048_50480201_79_dialog_content = "My good man, please, don't rile yourself up like this. Remember the divination just now?",
  ui_story_5048_50480201_80_dialog_content = "This kind of emotional distress is bound to stoke your inner fire, which could very easily lead to a rapid deterioration of your health. Should your nemesis strike while you're in this state, your savior will be nowhere to be found, and tragedy will follow.",
  ui_story_5048_50480201_81_dialog_content = "That actually makes sense, Master Li.",
  ui_story_5048_50480201_82_dialog_content = "I think you've been listening to too much of this charlatan's nonsense!",
  ui_story_5048_50480201_83_dialog_content = "Oh, for heaven's sake, Mister. Misfortune comes from the mouth. Be careful, lest you be made to eat those words.",
  ui_story_5048_50480201_84_dialog_content = "Hmm? Sir, the color of the space between your eyes is off. This could be an ominous sign...",
  ui_story_5048_50480201_85_dialog_content = "How about this—I'll provide you with a free divination, and we'll just forget about what happened here today. How does that sound?",
  ui_story_5048_50480201_86_dialog_content = "I don't believe you for a second!",
  ui_story_5048_50480201_87_dialog_content = "<color=#e8d9bb>Whoosh!!!</color>",
  ui_story_5048_50480201_88_dialog_content = "Hmm? You seem to have accidentally drawn two slips to form one divination. This is...",
  ui_story_5048_50480201_89_dialog_content = "Yin Horse and Yin Ox?!",
  ui_story_5048_50480201_90_dialog_content = "A dead ox pulls a wooden horse—neither able to advance. Sir, you must exercise great caution!",
  ui_story_5048_50480201_91_dialog_content = "Disaster may strike at any moment. You must eliminate all potential threats immediately and stay calm!",
  ui_story_5048_50480201_92_dialog_content = "Emm...",
  ui_story_5048_50480201_93_dialog_content = "Ernest?",
  ui_story_5048_50480201_94_dialog_content = "Urgh...",
  ui_story_5048_50480201_95_dialog_content = "What's wrong with you? If you have something to say, just say it...",
  ui_story_5048_50480201_96_dialog_content = "This is all coming to fruition rather quickly...",
  ui_story_5048_50480201_97_dialog_content = "Urrrgh...",
  ui_story_5048_50480201_98_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5048_50480201_99_dialog_content = "<color=#e8d9bb>A series of clinks and clatters!</color>",
  ui_story_5048_50480201_100_dialog_content = "I-I need some help over here!",
  ui_story_5048_50480201_101_dialog_content = "Help!",
  ui_story_5048_50480201_102_dialog_content = "Disaster strikes! Save his life!",
  ui_story_5048_50480201_103_dialog_content = "Help! Someone, help!",
  ui_story_5048_50480201_104_dialog_content = "Tianxian, what are you doing here?",
  ui_story_5048_50480201_105_dialog_content = "Miss Jiu? Princess Dantang? There truly is no story without coincidences, no meeting without predestination...",
  ui_story_5048_50480201_106_dialog_content = "Boss?!",
  ui_story_5048_50480201_107_dialog_content = "Boss, what's happened to you? Come on, wake up...",
  ui_story_5048_50480201_108_dialog_content = "Pale complexion, foaming at the mouth... Flaming red forehead?",
  ui_story_5048_50480201_109_dialog_content = "These symptoms... Isn't this <color=#FFB400>ravenflame</color> poisoning?",
  ui_story_5048_50480201_110_dialog_content = "Ravenflame is an analgesic with warming properties, but it can only be applied topically, not taken orally!",
  ui_story_5048_50480201_111_dialog_content = "Otherwise... Well, mild cases of ravenflame poisoning involve vomiting, diarrhea, and full-body numbness, while severe cases are marked by difficulty breathing, convulsions, delirium, and cardiac arrest.",
  ui_story_5048_50480201_112_dialog_content = "Such ruthless treachery...",
  ui_story_5048_50480201_113_dialog_content = "Jiu, press his fuquan acupoint and force him to spit out the poison first!",
  ui_story_5048_50480201_114_dialog_content = "Yes, Your Highness!",
  ui_story_5048_50480201_115_dialog_content = "Where's the nearest doctor? Can someone lead the way?",
  ui_story_5048_50480201_116_dialog_content = "I know! This way!",
  ui_story_5048_50480201_117_dialog_content = "Graagh!",
  ui_story_5048_50480201_118_dialog_content = "What?!",
  ui_story_5048_50480201_119_dialog_content = "Move!",
  ui_story_5048_50480201_120_dialog_content = "How did Eclipsites get inside Twin Pavilions Bay?!",
  ui_story_5048_50480201_121_dialog_content = "You take Ernest to the doctor first. We'll cover you.",
  ui_story_5048_50480201_122_dialog_content = "Remember to tell the doctor that Ernest has been poisoned with ravenflame.",
  ui_story_5048_50480201_123_dialog_content = "O-Okay, I will!",
  ui_story_5048_50480201_124_dialog_content = "Your Highness, please be careful. Don't push yourself too hard!",
  ui_story_5048_50480201_125_dialog_content = "Jiu, perhaps it's been too long since you last saw me handle an Eclipsite.",
  ui_story_5048_50480302_1_dialog_content = "Your Highness, all the Eclipsites have been wiped out. There isn't a single one left.",
  ui_story_5048_50480302_2_dialog_content = "I heard there's no Eclipsite rampant in Twin Pavilions Bay, so how exactly did the current situation come to pass?",
  ui_story_5048_50480302_3_dialog_content = "It's quite bizarre.",
  ui_story_5048_50480302_4_dialog_content = "Let's go back to the restaurant and take a look around.",
  ui_story_5048_50480302_5_dialog_content = "It's definitely you! Besides you, who else could be the murderer?",
  ui_story_5048_50480302_6_dialog_content = "My dear compatriots, I advise you not to cast such aspersions so carelessly—it may be detrimental to your fortune!",
  ui_story_5048_50480302_7_dialog_content = "We all heard it! It's you who used mean words to attack Mr. Ernest!",
  ui_story_5048_50480302_8_dialog_content = "Mr. Ernest collapsed right after you finished talking!",
  ui_story_5048_50480302_9_dialog_content = "Oh, heaven knows, causing harm to others would only bring negative consequences to my own life. I'd never do anything like that.",
  ui_story_5048_50480302_10_dialog_content = "Then how do you know this is a premeditated murder?",
  ui_story_5048_50480302_11_dialog_content = "It's definitely you! You're the murderer!",
  ui_story_5048_50480302_12_dialog_content = "A certain sentiment espoused by such mercenaries springs to mind—live by the sword, die by the sword.",
  ui_story_5048_50480302_13_dialog_content = "He has lived his life deceiving others, obfuscating the truth... Now, the truth cannot save him.",
  ui_story_5048_50480302_14_dialog_content = "Your Highness, Tianxian certainly has an oily tongue, but he's not a wicked-natured person.",
  ui_story_5048_50480302_15_dialog_content = "If he has indeed been wrongly accused, he's also worthy of pity.",
  ui_story_5048_50480302_16_dialog_content = "You're right, we shouldn't watch him go down and not even lift a finger to help just because of his past deceptions.",
  ui_story_5048_50480302_17_dialog_content = "Moreover, it was no easy for us to travel this far aboard The Shadowind. If any one of us were to be accused of such a charge...",
  ui_story_5048_50480302_18_dialog_content = "It would become even more difficult for us to establish trust and exchange information with those in charge here in the future.",
  ui_story_5048_50480302_19_dialog_content = "Your wisdom astounds me, Your Highness.",
  ui_story_5048_50480302_20_dialog_content = "You did it!",
  ui_story_5048_50480302_21_dialog_content = "Feel free to mobilize your mouths, but please, stay your hands!",
  ui_story_5048_50480302_22_dialog_content = "Grab him! Don't let him get away!",
  ui_story_5048_50480302_23_dialog_content = "Let's not get carried away now, everyone!",
  ui_story_5048_50480302_24_dialog_content = "Conclusive evidence is imperative before making accusations, let alone before demanding punishment. Li Tianxian may very well be the prime suspect here, but sufficient evidence must be found in order to convict him.",
  ui_story_5048_50480302_25_dialog_content = "Lady, you have a point, but how do we find evidence?",
  ui_story_5048_50480302_26_dialog_content = "Can you please tell us where Ernest went and what he did today?",
  ui_story_5048_50480302_27_dialog_content = "Our boss has a highly regular daily routine, and today was no different.",
  ui_story_5048_50480302_28_dialog_content = "It mainly includes inspecting the kitchen and sometimes observing customers' feedback in the restaurant.",
  ui_story_5048_50480302_29_dialog_content = "So what did he eat today?",
  ui_story_5048_50480302_30_dialog_content = "He doesn't have regular meals because each dish from the kitchen sets aside a tasting sample for him.",
  ui_story_5048_50480302_31_dialog_content = "Dishes are only brought to the customers' tables when he gives his approval.",
  ui_story_5048_50480302_32_dialog_content = "Besides this, are you certain that he absolutely did not eat anything else?",
  ui_story_5048_50480302_33_dialog_content = "No, I can assure you of that!",
  ui_story_5048_50480302_34_dialog_content = "In that case, the poison should be in the food Ernest sampled.",
  ui_story_5048_50480302_35_dialog_content = "Poison?",
  ui_story_5048_50480302_36_dialog_content = "That's right. The reason Ernest collapsed was due to the ravenflame poison in his system.",
  ui_story_5048_50480302_37_dialog_content = "Li Tianxian, did you enter the kitchen today?",
  ui_story_5048_50480302_38_dialog_content = "I swear upon the Scroll of Divine Ascension—no!",
  ui_story_5048_50480302_39_dialog_content = "Are there any witnesses who can testify to this effect?",
  ui_story_5048_50480302_40_dialog_content = "My benefactor... Mr. Victor!",
  ui_story_5048_50480302_41_dialog_content = "I began speaking with my benefactor as soon as I walked through the door. He can testify on my behalf!",
  ui_story_5048_50480302_42_dialog_content = "Erm... I can testify to this.",
  ui_story_5048_50480302_43_dialog_content = "What's going on... Does that mean he's not guilty?",
  ui_story_5048_50480302_44_dialog_content = "... If it's not him, then who did it?",
  ui_story_5048_50480302_45_dialog_content = "Thank you very much for your help, Princess Dantang. Without your intervention, I wouldn't have been able to cleanse myself of these suspicions had I jumped back into the ocean from whence we came.",
  ui_story_5048_50480302_46_dialog_content = "Don't misunderstand me, I didn't do it to help you—I'm just trying to get to the truth.",
  ui_story_5048_50480302_47_dialog_content = "If it's not him, then who else could it be? We don't even know if our boss is alive or dead. What do we do now?",
  ui_story_5048_50480302_48_dialog_content = "Don't worry. I won't give up on it since I've already involved myself in this matter.",
  ui_story_5048_50480302_49_dialog_content = "Miss, please seal the scene with your colleagues and refrain from touching even a single speck of dust. Also, I must ask that you compile a list of everyone who entered and exited the restaurant today.",
  ui_story_5048_50480302_50_dialog_content = "Okay, thank you... By the way, how should we address you?",
  ui_story_5048_50480302_51_dialog_content = "Just call me Dantang.",
  ui_story_5048_50480302_52_dialog_content = "Thank you, Miss Dantang!",
  ui_story_5048_50480302_53_dialog_content = "Princess Dantang, you're a truly beautiful and kind soul, and you handle everything with such calm.",
  ui_story_5048_50480302_54_dialog_content = "You've been cleared of suspicion, yet you still haven't made yourself scarce.",
  ui_story_5048_50480302_55_dialog_content = "I may not have been the culprit, but this all happened right before my eyes. I can't simply remain a passive observer.",
  ui_story_5048_50480302_56_dialog_content = "Do you have any ideas on how this case might be resolved?",
  ui_story_5048_50480302_57_dialog_content = "In the matter of resolving the case, your skills are superior to mine, so I naturally wouldn't dream of even attempting to instruct you on how to handle it.",
  ui_story_5048_50480302_58_dialog_content = "However, while being clawed at by the people just now, I did hear something interesting.",
  ui_story_5048_50480302_59_dialog_content = "They say that the owner of this restaurant, Ernest, was born into a family possessing tremendous wealth.",
  ui_story_5048_50480302_60_dialog_content = "But in order to realize his dream of creating world-class food, he went so far as to open a restaurant in Twin Pavilions Bay.",
  ui_story_5048_50480302_61_dialog_content = "He sets extremely strict requirements for the food he serves, and if this restaurant were ever to rank second in Twin Pavilions Bay, no one would dare claim their establishment ranked first.",
  ui_story_5048_50480302_62_dialog_content = "Who could such a prestigious figure have offended?",
  ui_story_5048_50480302_63_dialog_content = "Oh, that might be quite the list.",
  ui_story_5048_50480302_64_dialog_content = "Ernest's culinary skills are indeed faultless, but he's an aloof and arrogant man if there ever was one.",
  ui_story_5048_50480302_65_dialog_content = "He often scolds his apprentices, is constantly clashing with diners, and even...",
  ui_story_5048_50480302_66_dialog_content = "If you have something to say, say it. This isn't the time to be making a mystery of things.",
  ui_story_5048_50480302_67_dialog_content = "He also opened a rooftop cafe above the restaurant.",
  ui_story_5048_50480302_68_dialog_content = "For the local people here, congregating in a cafe is the same as going out for a meal in Longzhou.",
  ui_story_5048_50480302_69_dialog_content = "And the most important thing about a meal is not the food...",
  ui_story_5048_50480302_70_dialog_content = "... It's the matters to be discussed over the course of the meal.",
  ui_story_5048_50480302_71_dialog_content = "I understand. This restaurant is probably one of the main meeting points where local dignitaries discuss important affairs.",
  ui_story_5048_50480302_72_dialog_content = "Thank you for your input, Master Li.",
  ui_story_5048_50480302_73_dialog_content = "So I'm Master Li when I'm of use, and a mercenary trickster when I'm not... Your Highness, your powers of manipulation trump even mine.",
  ui_story_5048_50480302_74_dialog_content = "Tianxian, don't push your luck.",
  ui_story_5048_50480302_75_dialog_content = "If this matter involves local officials, it must be much more complex than we had previously anticipated.",
  ui_story_5048_50480302_76_dialog_content = "Your Highness, should we extricate ourselves from this mess while we still can?",
  ui_story_5048_50480302_77_dialog_content = "We could leave the case to the Umbraton Guild representative quartered at Twin Pavilions Bay, the one who's working with the Lin family to maintain order here.",
  ui_story_5048_50480302_78_dialog_content = "No, that won't do at all!",
  ui_story_5048_50480302_79_dialog_content = "Her Highness has yet to reveal her intentions. What are you blabbering about?",
  ui_story_5048_50480302_80_dialog_content = "I carried out a divination for you just now, Your Highness...",
  ui_story_5048_50480302_81_dialog_content = "If you allow this matter to develop free from your input, it will ultimately affect you adversely, and give rise to endless ramifications!",
  ui_story_5048_50480302_82_dialog_content = "Her Highness detests divination. How dare you even mention such a thing in her presence?",
  ui_story_5048_50480302_83_dialog_content = "Never mind, Jiu.",
  ui_story_5048_50480302_84_dialog_content = "The matter has arrived at this point already. I can't just walk away.",
  ui_story_5048_50480302_85_dialog_content = "We're strangers in this land, so it'll be difficult for us to start investigating the interpersonal relationships of the locals.",
  ui_story_5048_50480302_86_dialog_content = "But we still have one clue to follow up on.",
  ui_story_5048_50480302_87_dialog_content = "What clue?",
  ui_story_5048_50480302_88_dialog_content = "The herb, ravenflame.",
  ui_story_5048_50480401_1_dialog_content = "Excuse me, may I ask if you sell a Longzhou herb here called ravenflame?",
  ui_story_5048_50480401_2_dialog_content = "Nope, we don't have that.",
  ui_story_5048_50480401_3_dialog_content = "But I've heard people say that in Twin Pavilions Bay, as vast as it may be, only your store sells this herb.",
  ui_story_5048_50480401_4_dialog_content = "You can purchase it from whoever said that. We don't have it.",
  ui_story_5048_50480401_5_dialog_content = "Your attitude is atrocious... I'd like to speak to the proprietor!",
  ui_story_5048_50480401_6_dialog_content = "What's going on here? Tell me what the problem is, and let's keep this friendly, eh?",
  ui_story_5048_50480401_7_dialog_content = "Lady Sheol, they're here trying to cause trouble.",
  ui_story_5048_50480401_8_dialog_content = "Oh dear... How many times do I have to tell you?",
  ui_story_5048_50480401_9_dialog_content = "Anyone who enters this store is a customer, and customers are the sky above, the earth below, the very flesh of our beating hearts.",
  ui_story_5048_50480401_10_dialog_content = "How can I trust you to take care of the Twin Pavilions Bay branch when you carry on like this?",
  ui_story_5048_50480401_11_dialog_content = "But, Lady Sheol, didn't you say that the herb is only for the—",
  ui_story_5048_50480401_12_dialog_content = "Ahem, why don't you head into the back and check the inventory first.",
  ui_story_5048_50480401_13_dialog_content = "My dear, I'm really very sorry about that. Our newest shop assistant clearly doesn't quite understand our brand philosophy just yet.",
  ui_story_5048_50480401_14_dialog_content = "If you were offended, I apologize. Please allow me to offer you compensation for your distress—you're all welcome to a twelve percent discount when shopping here today!",
  ui_story_5048_50480401_15_dialog_content = "We just want to buy a herb called ravenflame.",
  ui_story_5048_50480401_16_dialog_content = "Little Lady...",
  ui_story_5048_50480401_17_dialog_content = "Just one look at you tells me you're not here to buy it, are you?",
  ui_story_5048_50480401_18_dialog_content = "Lady Sheol, it appears nothing gets past you.",
  ui_story_5048_50480401_19_dialog_content = "But we didn't come here with the intention of causing trouble. We're investigating a case.",
  ui_story_5048_50480401_20_dialog_content = "Have you heard about the incident regarding Mr. Ernest that took place this afternoon?",
  ui_story_5048_50480401_21_dialog_content = "Ah, yes. Ernest is embroiled in a conflict between the protectionist and free trade factions of Twin Pavilions Bay's western district.",
  ui_story_5048_50480401_22_dialog_content = "Something like this was bound to happen sooner or later.",
  ui_story_5048_50480401_23_dialog_content = "I was hoping you could do me a favor, Lady Sheol, and tell me whether you recall anyone purchasing any ravenflame.",
  ui_story_5048_50480401_24_dialog_content = "That way, we may be able to find the real culprit and secure a stable business environment in Twin Pavilions Bay.",
  ui_story_5048_50480401_25_dialog_content = "The local business environment won't be stabilized by solving this case alone. The last thing a businessperson like me can afford to do is upset my customers, so please don't make things even more difficult for me.",
  ui_story_5048_50480401_26_dialog_content = "My fair lady, I fear you fail to recognize who it is that stands before you.",
  ui_story_5048_50480401_27_dialog_content = "You're in the presence of Princess Zhuohua of Longzhou, Her Highness Dantang, a diplomatic envoy of the nation appointed by the higher-ups.",
  ui_story_5048_50480401_28_dialog_content = "If you offend her, you can forget about selling any more ravenflame. In fact, you might find it impossible to get your hands on any Longzhou products in the future.",
  ui_story_5048_50480401_29_dialog_content = "But if I have stock and no customers, I won't be bale to do business anyway.",
  ui_story_5048_50480401_30_dialog_content = "If that's the case, perhaps we can become your customers, Lady Sheol?",
  ui_story_5048_50480401_30X1_dialog_content = "Little Lady, it'd be an honor. Besides ravenflame, we have a wide range of other products more diverse than you could possibly imagine.",
  ui_story_5048_50480401_30X2_dialog_content = "A wide range of products, eh?",
  ui_story_5048_50480401_31_dialog_content = "According to this line of thought, you could say information on the person who purchased ravenflame might be considered a tradable item in your store?",
  ui_story_5048_50480401_32_dialog_content = "Hahaha! This particular commodity is a little tricky, but if you're really that sincere in your intentions, I can't just stand by and do nothing.",
  ui_story_5048_50480401_33_dialog_content = "Lady Sheol, rest assured that as long as the price is reasonable, I'll give you the cash right now.",
  ui_story_5048_50480401_34_dialog_content = "You Princesses of Longzhou certainly get to the point! However, the price of this item is not money, but a person.",
  ui_story_5048_50480401_35_dialog_content = "A person?",
  ui_story_5048_50480401_36_dialog_content = "A few days ago, riots broke out in the mercenary bazaar near Twin Pavilions Bay, which led to me losing a large amount of goods.",
  ui_story_5048_50480401_37_dialog_content = "But no one dares come forward to take responsibility for the matter.",
  ui_story_5048_50480401_38_dialog_content = "All I have to go on is a rumor that some unidentified mystery person appeared at the scene of the riot.",
  ui_story_5048_50480401_39_dialog_content = "I've been hoping someone could help me find this mystery person and uncover the truth behind the riot.",
  ui_story_5048_50480401_40_dialog_content = "Does this scoundrel have any distinguishing characteristics?",
  ui_story_5048_50480401_41_dialog_content = "They say the mystery person wielded a heavy sword, wore a dark cloak, and was covered in extremely sharp spikes.",
  ui_story_5048_50480401_42_dialog_content = "Whoa, this is no ordinary person.",
  ui_story_5048_50480401_43_dialog_content = "Uh-huh. Whether you go looking for this person or not is up to you.",
  ui_story_5048_50480401_44_dialog_content = "I have business to attend to right now, but feel free to hang out in the store for as long as you want. If you need anything else, just let the sales clerk know and I'll remind them to give you a discount!",
  ui_story_5048_50480401_45_dialog_content = "Thank you very much, Lady Sheol.",
  ui_story_5048_50480401_46_dialog_content = "Oh, that's right.",
  ui_story_5048_50480401_47_dialog_content = "If you do find that mystery person, be sure to treat them well!",
  ui_story_5048_50480401_48_dialog_content = "Why would we want to treat a villain like that well? This Lady Sheol sounds like Tianxian... I must admit, I'm rather confused.",
  ui_story_5048_50480401_49_dialog_content = "The things I speak of are nature's mysteries, things which are naturally difficult to understand.",
  ui_story_5048_50480401_50_dialog_content = "As for this Lady Sheol's mysterious ways, I can't tell if she's being ambiguous deliberately or intentionally!",
  ui_story_5048_50480401_51_dialog_content = "Deliberately or intentionally... Aren't they the same thing?",
  ui_story_5048_50480401_52_dialog_content = "Well, essentially, it now falls on Your Highness and Miss Jiu to search for this mystery person.",
  ui_story_5048_50480401_53_dialog_content = "I may be skilled with wit and words, but wielding weapons is work... best left to those with more experience.",
  ui_story_5048_50480401_54_dialog_content = "I'll head back to the restaurant and await the good news!",
  ui_story_5048_50480401_55_dialog_content = "So even Master Li has his moments of trepidation.",
  ui_story_5048_50480401_56_dialog_content = "As the saying goes, a wise man knows his limits and chooses his battles—only then can be become a hero. Besides, I won't be idling about either.",
  ui_story_5048_50480401_57_dialog_content = "When it comes to investigating rumors and ascertaining the facts of the situation, I still have a few tricks up my sleeve.",
  ui_story_5048_50480401_58_dialog_content = "Alright, let's split up and move on, perhaps we'll make faster progress. Master Li, thank you very much.",
  ui_story_5048_50480401_59_dialog_content = "Of course.",
  ui_story_5048_50480401_60_dialog_content = "Your Highness, the mercenary bazaar is just up ahead.",
  ui_story_5048_50480401_61_dialog_content = "It's much larger than I expected, but that shouldn't be a problem. Let's make as many inquiries as we can and look for any witnesses to the recent events here.",
  ui_story_5048_50480401_62_dialog_content = "Ahh! Eclipsites are here!",
  ui_story_5048_50480401_63_dialog_content = "Eclipsites again? And so soon after the last attack...",
  ui_story_5048_50480401_64_dialog_content = "Roar!",
  ui_story_5048_50480401_65_dialog_content = "Be careful, Your Highness!",
  ui_story_5048_50480401_66_dialog_content = "Take the thorns!",
  ui_story_5048_50480401_67_dialog_content = "Your Highness, are you injured?!",
  ui_story_5048_50480401_68_dialog_content = "No. That girl suddenly rushed up to me and helped me block the Eclipsite attack just now.",
  ui_story_5048_50480401_69_dialog_content = "That girl...",
  ui_story_5048_50480401_70_dialog_content = "Wielding a heavy sword, wearing a cloak, and covered in thorns?",
  ui_story_5048_50480401_71_dialog_content = "She's the one we're looking for!",
  ui_story_5048_50480401_72_dialog_content = "I'll go ahead and apprehend her now.",
  ui_story_5048_50480401_73_dialog_content = "Jiu, don't be rash.",
  ui_story_5048_50480401_74_dialog_content = "Why not? Isn't she the person we're looking for?",
  ui_story_5048_50480401_75_dialog_content = "She's the person we're looking for, but just look at her upstanding posture and resolute expression...",
  ui_story_5048_50480401_76_dialog_content = "She doesn't seem like someone who would intentionally commit evil deeds.",
  ui_story_5048_50480401_77_dialog_content = "Hmm...",
  ui_story_5048_50480401_78_dialog_content = "Graagh!",
  ui_story_5048_50480401_79_dialog_content = "Let there be light!",
  ui_story_5048_50480401_80_dialog_content = "From the way she's going after these Eclipsites and protecting passersby, I believe it's safe to assume she's a righteous person.",
  ui_story_5048_50480401_81_dialog_content = "Do you remember what Lady Sheol said?",
  ui_story_5048_50480401_82_dialog_content = "If you do find that mystery person, be sure to treat them well!",
  ui_story_5048_50480401_83_dialog_content = "She's probably not the instigator of the recent trouble here, but someone pursuing justice, like us.",
  ui_story_5048_50480401_84_dialog_content = "If that's the case, I'll lend her a hand.",
  ui_story_5048_50480401_85_dialog_content = "Roar!!!",
  ui_story_5048_50480401_86_dialog_content = "Huff... huff... huff...",
  ui_story_5048_50480401_87_dialog_content = "Noble warrior, please rest awhile—",
  ui_story_5048_50480401_88_dialog_content = "A-Are you here to catch me too?",
  ui_story_5048_50480401_89_dialog_content = "Sorry for startling you. We're from the continent of Longzhou and have been entrusted in this land by Lady Sheol to investigate the cause of the chaos at the bazaar several days ago.",
  ui_story_5048_50480401_90_dialog_content = "Can you tell us what's going on here?",
  ui_story_5048_50480401_91_dialog_content = "Lady Sheol...?",
  ui_story_5048_50480401_92_dialog_content = "Th-There are all kinds of people here, not just mercenaries and criminals, but also...",
  ui_story_5048_50480401_93_dialog_content = "Graagh!!",
  ui_story_5048_50480401_94_dialog_content = "Coughs... And we still have these Eclipsites breaking through.",
  ui_story_5048_50480401_95_dialog_content = "A place like this... will stain the hem of such a beautiful noblewoman's garments.",
  ui_story_5048_50480401_96_dialog_content = "While there are no other Eclipsites attacking... seize this chance and go home as quickly as you can.",
  ui_story_5048_50480401_97_dialog_content = "If I can prove that a noblewoman can fight like a mercenary, will you change your mind and help me?",
  ui_story_5048_50480401_98_dialog_content = "Roar!",
  ui_story_5048_50480401_99_dialog_content = "... F-Fine! I'll leave this to you!",
  ui_story_5048_50480402_1_dialog_content = "I've finished checking—not a single one has slipped through the cracks.",
  ui_story_5048_50480402_2_dialog_content = "Thanks for being so willing to help me...",
  ui_story_5048_50480402_3_dialog_content = "I thought my appearance... might scare you.",
  ui_story_5048_50480402_4_dialog_content = "I can clearly see you're very charming and adorable. You remind me of my younger sister. How could you possibly scare me?",
  ui_story_5048_50480402_5_dialog_content = "These... thorns... on my body...",
  ui_story_5048_50480402_6_dialog_content = "Do they hurt?",
  ui_story_5048_50480402_7_dialog_content = "I'm... used to them.",
  ui_story_5048_50480402_8_dialog_content = "Although these thorns bring you pain, you can also use them to fight and help those in need...",
  ui_story_5048_50480402_9_dialog_content = "Your appearance is truly admirable!",
  ui_story_5048_50480402_10_dialog_content = "Oh...",
  ui_story_5048_50480402_11_dialog_content = "I'm Dantang, and this here beside me is Jiu.",
  ui_story_5048_50480402_12_dialog_content = "We're from Longzhou, and are currently investigating a case here.",
  ui_story_5048_50480402_13_dialog_content = "Lady Sheol told us that perhaps you might know something, which is why we took the liberty of coming here to search for you.",
  ui_story_5048_50480402_14_dialog_content = "So... that's why you're here.",
  ui_story_5048_50480402_15_dialog_content = "Can you tell us your name now?",
  ui_story_5048_50480402_16_dialog_content = "Areia...",
  ui_story_5048_50480402_17_dialog_content = "My name is Areia.",
  ui_story_5048_50480501_1_dialog_content = "Miss Areia, when you just mentioned that someone was after you, were you speaking the truth?",
  ui_story_5048_50480501_2_dialog_content = "You can tell us about it, if you don't mind, that is.",
  ui_story_5048_50480501_3_dialog_content = "Erm... D-Don't judge me by how I look, I'm actually a wandering mercenary.",
  ui_story_5048_50480501_4_dialog_content = "I've had to live with an awful disease ever since I was born—these black thorns growing on my body.",
  ui_story_5048_50480501_5_dialog_content = "So now I wander from place to place, hoping to find a way to cure my condition.",
  ui_story_5048_50480501_6_dialog_content = "I only arrived at Twin Pavilions Bay not long ago.",
  ui_story_5048_50480501_7_dialog_content = "I ran into a high-paying employer at the mercenary bazaar.",
  ui_story_5048_50480501_8_dialog_content = "Hey, just look at you...",
  ui_story_5048_50480501_9_dialog_content = "Do you know any tricks that can hurt without leaving a trace?",
  ui_story_5048_50480501_10_dialog_content = "I-I don't know such things...",
  ui_story_5048_50480501_11_dialog_content = "Trust me, the payment will make you happy.",
  ui_story_5048_50480501_12_dialog_content = "I'd never hurt anyone without a good reason...",
  ui_story_5048_50480501_13_dialog_content = "Humph, trying to act all high and righteous here?",
  ui_story_5048_50480501_14_dialog_content = "People like you are a dime a dozen; you're nothing special.",
  ui_story_5048_50480501_15_dialog_content = "People... like me...?",
  ui_story_5048_50480501_16_dialog_content = "I thought if I followed him, I could find people afflicted with the same condition as me, and perhaps they could tell me what causes this kind of awful disease.",
  ui_story_5048_50480501_17_dialog_content = "But later I found out... he didn't know anyone who understood these things.",
  ui_story_5048_50480501_18_dialog_content = "In fact, it turned he had actually found some other way to carry out his plans.",
  ui_story_5048_50480501_19_dialog_content = "But you didn't give up your search just because of this?",
  ui_story_5048_50480501_20_dialog_content = "I just couldn't stand by... and watch as people were getting hurt, so I kept searching on my own.",
  ui_story_5048_50480501_21_dialog_content = "But I was too careless... I exposed myself at the bazaar a few days ago.",
  ui_story_5048_50480501_22_dialog_content = "The trouble at the bazaar was actually the result of him catching me.",
  ui_story_5048_50480501_23_dialog_content = "So those Eclipsites were actually brought here by that employer?",
  ui_story_5048_50480501_24_dialog_content = "I'm really, really sorry... This is all my fault!",
  ui_story_5048_50480501_25_dialog_content = "So, I can't just give up and let his plan succeed.",
  ui_story_5048_50480501_26_dialog_content = "It seems the rights and wrongs here are no fewer than in Longzhou.",
  ui_story_5048_50480501_27_dialog_content = "The way of the world is to seek personal gain.",
  ui_story_5048_50480501_28_dialog_content = "With so much money flowing in and out of Twin Pavilions Bay's trade channels, how could this place not attract both good and evil?",
  ui_story_5048_50480501_29_dialog_content = "But we've only just arrived. Why is it that we've already encountered so many strange happenings?",
  ui_story_5048_50480501_30_dialog_content = "... You raise a good point, Jiu. Perhaps these are not isolated incidents. There may be some hidden connection between them...",
  ui_story_5048_50480501_31_dialog_content = "Areia, have you discovered any useful information during your investigation?",
  ui_story_5048_50480501_32_dialog_content = "Hmm... The employer I mentioned is the head of a trade group in the western district of Twin Pavilions Bay.",
  ui_story_5048_50480501_33_dialog_content = "He is a member of what the locals call the free trade faction and holds a strong hatred for the protectionists...",
  ui_story_5048_50480501_34_dialog_content = "So, his target is someone from the protectionist faction.",
  ui_story_5048_50480501_35_dialog_content = "Everything is connected.",
  ui_story_5048_50480501_36_dialog_content = "I remember Lady Sheol mentioning that Ernest is embroiled in a conflict between the protectionist and free trade factions.",
  ui_story_5048_50480501_37_dialog_content = "Actually... I discovered the identity of the target during my investigation... I wanted to deal with the Eclipsites and go find a man called Victor.",
  ui_story_5048_50480501_38_dialog_content = "What did you say?",
  ui_story_5048_50480501_39_dialog_content = "The target was... Mr. Victor, the Umbraton Guild representative assigned to Twin Pavilions Bay.",
  ui_story_5048_50480501_40_dialog_content = "Oh no...",
  ui_story_5048_50480501_41_dialog_content = "Victor is the name of Tianxian's benefactor!",
  ui_story_5048_50480501_42_dialog_content = "A-Achoo!",
  ui_story_5048_50480501_43_dialog_content = "Master Li, are you alright?",
  ui_story_5048_50480501_44_dialog_content = "It's nothing, please, go on.",
  ui_story_5048_50480501_45_dialog_content = "... So of course I find this all very distressing, as Ernest is my friend and the one person who drives me to be more resolute.",
  ui_story_5048_50480501_46_dialog_content = "Although he has a sharp tongue, and I occasionally strike back with a few criticisms of my own, I know his point of view is actually usually very reasonable.",
  ui_story_5048_50480501_47_dialog_content = "He isn't aware of this yet, but I've already started pushing forward the practices of the protectionists, with a view to making them familiar to all.",
  ui_story_5048_50480501_48_dialog_content = "But now, if he's truly done for, the protectionists will be without their most influential champion...",
  ui_story_5048_50480501_49_dialog_content = "Perhaps I should reconsider my choice of supporting the protectionists.",
  ui_story_5048_50480501_50_dialog_content = "As the Umbraton Guild representative for Twin Pavilions Bay, Mr. Victor has always been known for his hands-off attitude toward trade groups.",
  ui_story_5048_50480501_51_dialog_content = "Recently though, he decided not to turn a blind eye.",
  ui_story_5048_50480501_52_dialog_content = "He was also planning to promote the proposals of the protectionists, thus making him a target of the free traders.",
  ui_story_5048_50480501_53_dialog_content = "But Mr. Victor was not the victim of the plot just now. Instead, the restaurant owner, Ernest, was poisoned and collapsed.",
  ui_story_5048_50480501_54_dialog_content = "Could the free traders have had two targets?",
  ui_story_5048_50480501_55_dialog_content = "Jiu, do you remember how Ernest would sample all of the food coming out of the kitchen?",
  ui_story_5048_50480501_56_dialog_content = "The restaurant server did mention this fact.",
  ui_story_5048_50480501_57_dialog_content = "Mr. Victor didn't have the time to eat because Tianxian was divining for him.",
  ui_story_5048_50480501_58_dialog_content = "... The killer tampered with Victor's food.",
  ui_story_5048_50480501_59_dialog_content = "Ernest was poisoned because he sampled Victor's dishes and ended up the victim instead of the intended target!",
  ui_story_5048_50480501_60_dialog_content = "If this would-be killer had known in advance that Ernest, a protectionist, had a habit of tasting food before serving...",
  ui_story_5048_50480501_61_dialog_content = "Poisoning would have been the perfect strategy to kill two birds with one stone.",
  ui_story_5048_50480501_62_dialog_content = "So it turns out Tianxian actually can save lives sometimes.",
  ui_story_5048_50480501_63_dialog_content = "Speaking of which, Miss Areia... did you say just now that the culprit has returned to the mercenary bazaar?",
  ui_story_5048_50480501_64_dialog_content = "Erm... he's still searching for someone to help him get rid of Victor.",
  ui_story_5048_50480501_65_dialog_content = "Is this conspiracy against Victor still ongoing?",
  ui_story_5048_50480501_66_dialog_content = "Help! Help!",
  ui_story_5048_50480501_67_dialog_content = "On death's door!",
  ui_story_5048_50480501_68_dialog_content = "Roar!",
  ui_story_5048_50480501_69_dialog_content = "Didn't you say I would meet a virtuous person who'd turn misfortunes into blessings?",
  ui_story_5048_50480501_70_dialog_content = "All I can see here are Eclipsites! Where's my virtuous savior?!",
  ui_story_5048_50480501_71_dialog_content = "Ah, I didn't think things would turn out like this either. The virtuous person destined to save your life wasn't a Lumopolis noble, nor was it the Princess of Longzhou...",
  ui_story_5048_50480501_72_dialog_content = "It was me, a shameless fortune teller. I'm so sorry!",
  ui_story_5048_50480601_1_dialog_content = "Mr. Victor!",
  ui_story_5048_50480601_2_dialog_content = "Miss. Dantang!",
  ui_story_5048_50480601_3_dialog_content = "Are you alright? You're not hurt at all?",
  ui_story_5048_50480601_4_dialog_content = "I'm fine, I'm not hurt...",
  ui_story_5048_50480601_5_dialog_content = "And where is Tianxian?",
  ui_story_5048_50480601_6_dialog_content = "Master Li led away all of the Eclipsites on his own in order to save me...",
  ui_story_5048_50480601_7_dialog_content = "Please rescue him before it's too late!",
  ui_story_5048_50480601_8_dialog_content = "Why couldn't he predict that he'd come face-to-face with disaster today?",
  ui_story_5048_50480601_9_dialog_content = "I'm glad you've finally learned to crack a joke, but now's not the time.",
  ui_story_5048_50480601_10_dialog_content = "Sorry, Your Highness. I'm afraid he might've just thrown his life away in an attempt to display his bravery.",
  ui_story_5048_50480601_11_dialog_content = "... Let's go ahead and take a look!",
  ui_story_5048_50480601_12_dialog_content = "Jiu, look!",
  ui_story_5048_50480601_13_dialog_content = "Roar! Roar!!!",
  ui_story_5048_50480601_14_dialog_content = "Why are these Eclipsites huddling together and roaring at the ground?",
  ui_story_5048_50480601_15_dialog_content = "It's like they're surrounding someone... Hang on, could it be...",
  ui_story_5048_50480601_16_dialog_content = "Graaagh!",
  ui_story_5048_50480601_17_dialog_content = "They've spotted us!",
  ui_story_5048_50480601_18_dialog_content = "Then let's wipe them out on the double!",
  ui_story_5048_50480602_1_dialog_content = "Tianxian...",
  ui_story_5048_50480602_2_dialog_content = "Strange, he's not here?",
  ui_story_5048_50480602_3_dialog_content = "Hmm?",
  ui_story_5048_50480602_4_dialog_content = "Heheheh...",
  ui_story_5048_50480602_5_dialog_content = "Jiu, look again. What were the Eclipsites surrounding just now?",
  ui_story_5048_50480602_6_dialog_content = "A manhole cover leading down into the sewers...",
  ui_story_5048_50480602_7_dialog_content = "Is there a sugar figurine jammed into it?",
  ui_story_5048_50480602_8_dialog_content = "It seems he's already made his cunning getaway, so we don't need to worry anymore.",
  ui_story_5048_50480602_9_dialog_content = "Miss. Dantang!",
  ui_story_5048_50480602_10_dialog_content = "Areia?",
  ui_story_5048_50480602_11_dialog_content = "What's the situation? Has Lady Sheol been informed of what's going on?",
  ui_story_5048_50480602_12_dialog_content = "Yes! Also...",
  ui_story_5048_50480602_13_dialog_content = "Also, I brought the guilds along.",
  ui_story_5048_50480602_14_dialog_content = "Lady Sheol...",
  ui_story_5048_50480602_15_dialog_content = "We finally meet again, Little Lady.",
  ui_story_5048_50480602_16_dialog_content = "Lady Sheol, thank you so much for your timely appearance. Now that we're all here, let's hurry up and catch that culprit.",
  ui_story_5048_50480602_17_dialog_content = "Don't worry about that. As you helped us find the key witness...",
  ui_story_5048_50480602_18_dialog_content = "The Umbraton Guild, in conjunction with organizations such as the Lin Guild and the Courier Union, quickly caught the culprit.",
  ui_story_5048_50480602_19_dialog_content = "Just as you predicted, he admitted to also being the one who planned the Eclipsite mayhem of late.",
  ui_story_5048_50480602_20_dialog_content = "Now, on behalf of our guilds, we solemnly thank you, Envoy of Longzhou, Princess Dantang, for your invaluable help.",
  ui_story_5048_50480602_21_dialog_content = "Thank you, Princess Dantang, for rooting out the evildoers for us!",
  ui_story_5048_50480602_22_dialog_content = "Thank you, Princess Dantang! Thank you, Princess Dantang!",
  ui_story_5048_50480602_23_dialog_content = "I get the feeling Lady Sheol knew who the real culprit was from the beginning... but she wanted to make the arrest in our names.",
  ui_story_5048_50480602_24_dialog_content = "Twin Pavilions Bay was originally divided into two parts, and was ruled by the Umbraton Guild and the Lin Guild.",
  ui_story_5048_50480602_25_dialog_content = "Their conflicting interests are so intertwined, I'm afraid they themselves were unable to resolve the matter.",
  ui_story_5048_50480602_26_dialog_content = "We, being outsiders, caught the culprit and thus became their shield.",
  ui_story_5048_50480602_27_dialog_content = "So, we were being used?",
  ui_story_5048_50480602_28_dialog_content = "The benefits arising from this resolution are not unilateral—they have also helped us.",
  ui_story_5048_50480602_29_dialog_content = "We have now established our reputation, so soon after arriving at Twin Pavilions Bay. Things will now be much easier for us in the future.",
  ui_story_5048_50480602_30_dialog_content = "Little ladies, have you finished whispering to each other over there?",
  ui_story_5048_50480602_31_dialog_content = "If there's anything you're dissatisfied with, please feel free to let me know. The guild representatives are all here and are sure to help you resolve any problems you might have.",
  ui_story_5048_50480602_32_dialog_content = "You've already done so much, Lady Sheol, and everyone.",
  ui_story_5048_50480602_33_dialog_content = "I was just wondering, how are we going to handle the dispute between the free traders and the protectionists in Twin Pavilions Bay in the future?",
  ui_story_5048_50480602_34_dialog_content = "I've been thinking a lot about that today, and I've finally come to understand something.",
  ui_story_5048_50480602_35_dialog_content = "We can all agree that Twin Pavilions Bay needs fair systems and suitable controls.",
  ui_story_5048_50480602_36_dialog_content = "Regardless of whether support from the other trade faction is there in the future, I will continue to promote the proposals of the protectionists.",
  ui_story_5048_50480602_37_dialog_content = "Even if this imposes certain constraints on the activities and interests of other existing factions.",
  ui_story_5048_50480602_38_dialog_content = "Constraints...",
  ui_story_5048_50480602_39_dialog_content = "<color=#e8d9bb>Chirp, chirp, screech—</color>",
  ui_story_5048_50480602_39X1_dialog_content = "<color=#e8d9bb>Sheol gazes at the sky with a thoughtful look.</color>",
  ui_story_5048_50480602_40_dialog_content = "All of these constraints will lead to far greater benefits.",
  ui_story_5048_50480602_41_dialog_content = "What do you think, Little Lady?",
  ui_story_5048_50480602_42_dialog_content = "Hmm, I have no objections.",
  ui_story_5048_50480602_43_dialog_content = "Well, having the support of the Princess of Longzhou makes me feel even more at ease.",
  ui_story_5048_50480602_44_dialog_content = "But aren't you afraid you'll have to face defamation attempts from opposition factions in the future?",
  ui_story_5048_50480602_45_dialog_content = "Afraid... Of course I'm afraid.",
  ui_story_5048_50480602_46_dialog_content = "Perhaps I should consider hiring a bodyguard just like you.",
  ui_story_5048_50480602_47_dialog_content = "But as Master Li said, I was born under a lucky star, and can always count on the help of virtuous benefactors to turn my misfortunes into blessings...",
  ui_story_5048_50480602_48_dialog_content = "Hey, why don't I ask Master Li to be my bodyguard?",
  ui_story_5048_50480602_49_dialog_content = "Ahem, I advise you to reconsider.",
  ui_story_5048_50480602_50_dialog_content = "A-Achoo!",
  ui_story_5048_50480602_51_dialog_content = "Judging from all the sneezing, there must really be a lot of people thinking about me today... but why hasn't anyone come to me for divination?",
  ui_story_5048_50480602_52_dialog_content = "<color=#e8d9bb>Splish, splash</color>",
  ui_story_5048_50480602_53_dialog_content = "The Princess of Ye, the Prince of Ji... The Lin Family Incident, The Shadowind?",
  ui_story_5048_50480602_54_dialog_content = "Tch, I need to figure this out carefully.",
  ui_story_5048_50480602_55_dialog_content = "<color=#e8d9bb>Whooooosh!</color>",
  ui_story_5048_50480602_56_dialog_content = "Yang Snake above, Yin Ox below. Spring gives rise to Ox and Snake, preparing for four seasons of tumult. Could it be that Longzhou...",
  ui_story_5048_50480602_57_dialog_content = "No, that can't be right. I must just be too tired for divination right now... right?",
  ui_story_5048_50480602_58_dialog_content = "Here he is! Here he is!",
  ui_story_5048_50480602_59_dialog_content = "Eating alone! Eating alone!",
  ui_story_5048_50480602_60_dialog_content = "What are you talking about? I haven't eaten anything yet, I've just been waiting for you two.",
  ui_story_5048_50480602_61_dialog_content = "Burned out! Burned out!",
  ui_story_5048_50480602_62_dialog_content = "Find Dantang! Find Dantang!",
  ui_story_5048_50480602_63_dialog_content = "Mind your little beak! Remember to call her Princess Dantang when you go out!",
  ui_story_5048_50480602_64_dialog_content = "Princess?",
  ui_story_5048_50480602_65_dialog_content = "Princess?",
  ui_story_5048_50480602_66_dialog_content = "Heh, this kind of thing isn't optional.",
  ui_story_5048_50480602_67_dialog_content = "As previously mentioned by the Lin Guild, I am Dantang, Envoy of Longzhou's Ji Kingdom.",
  ui_story_5048_50480602_68_dialog_content = "I stand here today, representing the resources and goodwill that can be provided from across the sea.",
  ui_story_5048_50480602_69_dialog_content = "We hope that this transoceanic trade route can not only solidify communications with the guilds of Umbraton...",
  ui_story_5048_50480602_70_dialog_content = "But that it can also reach Lumopolis, the Illumina Federation, and even the distant reaches of Northland.",
  ui_story_5048_50480602_71_dialog_content = "...",
  ui_story_5048_50480602_72_dialog_content = "Of course, the culture and goods of Astra can also enter the wider continent of Longzhou through this trade route.",
  ui_story_5048_50480602_72X1_dialog_content = "The unique equipment and resources of Astra may also help Longzhou overcome threats to the coastline...",
  ui_story_5048_50480602_73_dialog_content = "In summary, this is a trade channel that can connect two continents!",
  ui_story_5048_50480602_74_dialog_content = "Ladies and gentlemen, this is not just a dream, but a reality within our grasp.",
  ui_story_5048_50480602_75_dialog_content = "Early adopters can seize this opportunity to embark on a road destined to span the ages.",
  ui_story_5048_50480602_76_dialog_content = "With its existence, our struggle against those creatures of darkness will also usher in more opportunities.",
  ui_story_5048_50480602_77_dialog_content = "Alright!",
  ui_story_5048_50480602_78_dialog_content = "Well said. I haven't heard such hopeful words in a long time.",
  ui_story_5048_50480602_79_dialog_content = "Shadowlord... Shadowlord is here as well!",
  ui_story_5048_50480602_80_dialog_content = "The ruler of Umbraton, Lord Istvan!",
  ui_story_5048_50480602_81_dialog_content = "I gladly accept your courage and sincerity, on behalf of my organization.",
  ui_story_5048_50480602_82_dialog_content = "Let's see if the fruits of our cooperation can truly carry the future of our two continents.",
  ui_story_5048_50480602_83_dialog_content = "I think it will at least serve as a beginning.",
  ui_story_5048_50480602_84_dialog_content = "A fine beginning for a new era.",
  ui_story_5048_50480602_85_dialog_content = "<color=#e8d9bb>Whoosh, whoosh—</color>",
  ui_story_5048_50480602_86_dialog_content = "The wind rises.",
  ui_story_5048_50480602_87_dialog_content = "A sweet rain softens Twin Pavilions Bay...",
  ui_story_5048_50480602_88_dialog_content = "It's soon coming.",
  ui_story_5048_50480701_1_dialog_content = "<color=#e8d9bb>A few days later...</color>",
  ui_story_5048_50480701_2_dialog_content = "Your Highness, this mountain path is fraught with peril, please be careful!",
  ui_story_5048_50480701_3_dialog_content = "The best herbs often grow in the most dangerous places.",
  ui_story_5048_50480701_4_dialog_content = "When I was young, my whole family caught the plague and went to the most dangerous mountain peaks to collect herbs.",
  ui_story_5048_50480701_5_dialog_content = "The current terrain, with its small hills, is not a problem in the slightest.",
  ui_story_5048_50480701_6_dialog_content = "Heavens... Your Highness, you might not be tired, but you've exhausted us all.",
  ui_story_5048_50480701_7_dialog_content = "That restaurant owner, Ernest, has already been cured.",
  ui_story_5048_50480701_8_dialog_content = "Why are we still looking for herbs for him?",
  ui_story_5048_50480701_9_dialog_content = "Although his life is no longer in any great danger, his health must have been severely affected.",
  ui_story_5048_50480701_10_dialog_content = "Right now, only a very specific selection of herbs can quickly nourish his body and mind to make up for the deficiency remaining in his constitution.",
  ui_story_5048_50480701_11_dialog_content = "Mr. Ernest and I share a profound appreciation of each other's strengths. Such friendship is truly rare, and I cherish this bond immensely.",
  ui_story_5048_50480701_12_dialog_content = "So of course I should show him my gratitude right away and let him experience a traditional Longzhou tonic.",
  ui_story_5048_50480701_13_dialog_content = "This could also be considered a much-told tale in the history of culinary exchange between Astra and Longzhou.",
  ui_story_5048_50480701_14_dialog_content = "But can the herbs of Longzhou really be found in this place?",
  ui_story_5048_50480701_15_dialog_content = "I have already confirmed this with the locals.",
  ui_story_5048_50480701_16_dialog_content = "This place doesn't have our herbs, but there's a useful type known as the red wolfberry, which they have always seen as merely a weed.",
  ui_story_5048_50480701_17_dialog_content = "It rained quite heavily a few days ago, so now that the sky has cleared, it should be the perfect time for the red wolfberry to flourish.",
  ui_story_5048_50480701_18_dialog_content = "Red fruit ahead!",
  ui_story_5048_50480701_19_dialog_content = "Yummy! So yummy!",
  ui_story_5048_50480701_20_dialog_content = "Seeing as how you two seem so adept at foraging in the wild, you can stop asking me for melons and dates every day, from now on.",
  ui_story_5048_50480701_21_dialog_content = "Wait, the fruit Squawk and Jabber are eating...",
  ui_story_5048_50480701_22_dialog_content = "It's red wolfberry!",
  ui_story_5048_50480701_23_dialog_content = "We found it! We actually found it!",
  ui_story_5048_50480701_24_dialog_content = "Oh, so this little red fruit is a herbal medicine?",
  ui_story_5048_50480701_25_dialog_content = "Tianxian, don't eat too many of them raw like that, they quickly raise your inner fire and cause diarrhea.",
  ui_story_5048_50480701_26_dialog_content = "Miss Jiu, you really should have said something sooner...",
  ui_story_5048_50480701_27_dialog_content = "Squawk, Jabber, did you hear that? Eat too much and you'll only have yourselves to blame for the consequences...",
  ui_story_5048_50480701_28_dialog_content = "Enough messing around—remember to pick as much as you can and fill up your baskets!",
  ui_story_5048_50480701_29_dialog_content = "Yes, Princess!",
  ui_story_5048_50480701_30_dialog_content = "Of course.",
  ui_story_5048_50480701_31_dialog_content = "Sisters, I wonder what the two of you are doing right now...",
  ui_story_5048_50480701_32_dialog_content = "Everything is just fine here, and matters are progressing in an orderly manner.",
